  const body = [
    ...(attempt.correctAnswer?.trim() ? [`**Correct answer:** ${markdownText(attempt.correctAnswer)}`] : []),
    ...(attempt.feedback?.trim() ? ["", `**${attempt.correctAnswer?.trim() ? "Explanation" : "Feedback"}:** ${markdownText(attempt.feedback)}`] : []),
